<?php
/**
 * Hortulus web – texts of the site pages (the garden app itself has its own, much larger catalog).
 */

declare(strict_types=1);

const LANGS = ['nl' => 'Nederlands', 'fr' => 'Français', 'en' => 'English'];

function lang(): string
{
    $l = $_SESSION['lang'] ?? null;
    if (!$l) {
        $accept = strtolower((string) ($_SERVER['HTTP_ACCEPT_LANGUAGE'] ?? ''));
        foreach (array_keys(LANGS) as $code) {
            if (str_starts_with($accept, $code)) {
                $l = $code;
                break;
            }
        }
    }
    return isset(LANGS[$l]) ? $l : DEFAULT_LANG;
}

function t(string $key, array $params = []): string
{
    static $all = null;
    $all ??= texts();
    $text = $all[lang()][$key] ?? $all['en'][$key] ?? $key;
    foreach ($params as $name => $value) {
        $text = str_replace('{' . $name . '}', (string) $value, $text);
    }
    return $text;
}

